1	/**
2	 * open-pull-request.ts — the pull request standing open on a head branch, as both
3	 * halves of the update lane ask it.
4	 *
5	 * The update run asks before it opens one, so a second run edits the pull request
6	 * it already made instead of failing on a duplicate. The notice asks before it
7	 * dispatches an update at all, so a daily cron does not start a run per day for a
8	 * release that is still waiting on one pull request.
9	 *
10	 * The answer is a number, `0` for none, and never an exception: a read that fails is
11	 * not evidence that no pull request exists, so each caller gets to decide -- the
12	 * update opens or edits as though none is there (which is recoverable), and the
13	 * notice dispatches rather than silently skipping a release.
14	 *
15	 * `token` is the update lane's PAT, and the notice must pass it. A workflow that
16	 * declares `permissions` gets `none` for every scope it does not list, and
17	 * `atomaton-new-release.yml` lists `contents` and `issues` only: on a private
18	 * repository its own token cannot list pull requests at all. The refusal would come
19	 * back as this function's `0` -- "no pull request is open" -- and the cron would
20	 * dispatch the same update every day for as long as the release is waiting. Reading
21	 * as the identity that may is cheaper than the alternative, which is adding
22	 * `pull-requests: read` to the permissions of the workflow that writes the notice.
23	 */
24	import { ghAs, ghRead } from "../../../adapters/github/gh.ts";
25	
26	/** The read, as `token` when one is given and as the ambient identity otherwise. */
27	function listOpenForHead(token: string, repo: string, branch: string) {
28	  const argv = ["pr", "list", "--repo", repo, "--head", branch, "--state", "open", "--json", "number"] as const;
29	  return token.trim() === "" ? ghRead(...argv) : ghAs(token.trim(), ...argv);
30	}
31	
32	export function openPrForHead(repo: string, branch: string, token = ""): number {
33	  const result = listOpenForHead(token, repo, branch);
34	  if (result.code !== 0) {
35	    // Named rather than swallowed: `0` is the answer that dispatches an update (or
36	    // opens a second pull request), so the reason it was given belongs in the log of
37	    // the run that acted on it.
38	    const why = (result.stderr || result.stdout).split("\n")[0] ?? "";
39	    console.error(`WARN could not list open pull requests on ${branch}: ${why || `gh exited ${result.code}`}`);
40	    return 0;
41	  }
42	  try {
43	    const parsed = JSON.parse(result.stdout || "[]") as Array<{ number?: unknown }>;
44	    const number = Number(parsed[0]?.number ?? 0);
45	    return Number.isInteger(number) && number > 0 ? number : 0;
46	  } catch {
47	    return 0;
48	  }
